This source implements task add, edit, complete, delete, filtering and local storage. A source listing is not evidence that a React preview or persistence has run.

```jsx
import React, { useEffect, useState } from 'react';
export default function TasksApp() {
  const [tasks, setTasks] = useState(() => JSON.parse(localStorage.getItem('tasks') || '[]'));
  const [title, setTitle] = useState('');
  const [filter, setFilter] = useState('all');
  useEffect(() => localStorage.setItem('tasks', JSON.stringify(tasks)), [tasks]);
  const visible = tasks.filter(t => filter === 'all' || (filter === 'completed' ? t.done : !t.done));
  return <main className="p-6 rounded-2xl bg-white">
    <h1>My Tasks</h1>
    <form onSubmit={e => { e.preventDefault(); if (!title.trim()) return; setTasks([...tasks, {id:crypto.randomUUID(), title:title.trim(), done:false}]); setTitle(''); }}>
      <input aria-label="New task" value={title} onChange={e => setTitle(e.target.value)} />
      <button>Add Task</button>
    </form>
    <select aria-label="Task filter" value={filter} onChange={e => setFilter(e.target.value)}>
      <option value="all">All</option><option value="active">Active</option><option value="completed">Completed</option>
    </select>
    {visible.map(task => <article key={task.id}>
      <input type="checkbox" aria-label={task.title} checked={task.done} onChange={() => setTasks(tasks.map(t => t.id === task.id ? {...t, done:!t.done} : t))} />
      <input aria-label={'Edit '+task.title} value={task.title} onChange={e => setTasks(tasks.map(t => t.id === task.id ? {...t,title:e.target.value} : t))} />
      <button onClick={() => setTasks(tasks.filter(t => t.id !== task.id))}>Delete</button>
    </article>)}
  </main>;
}
```

